import numpy as np

def pre_post(x, split):
    x = np.asarray(x, dtype=float)
    a, b = x[:split], x[split:]
    se = np.sqrt(a.var(ddof=1) / len(a) + b.var(ddof=1) / len(b))
    return round(float(a.mean()), 4), round(float(b.mean()), 4), round(float((b.mean() - a.mean()) / se), 4)

